package com.netflix.spinnaker.clouddriver.deploy;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

import com.netflix.spectator.api.NoopRegistry;
import com.netflix.spectator.api.Registry;
import com.netflix.spinnaker.clouddriver.security.AccountDefinitionSecretManager;
import com.netflix.spinnaker.clouddriver.security.config.SecurityConfig;
import com.netflix.spinnaker.clouddriver.security.resources.AccountNameable;
import com.netflix.spinnaker.clouddriver.security.resources.ApplicationNameable;
import com.netflix.spinnaker.clouddriver.security.resources.ResourcesNameable;
import com.netflix.spinnaker.fiat.model.resources.ResourceType;
import com.netflix.spinnaker.fiat.shared.FiatPermissionEvaluator;
import java.io.Serializable;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import org.springframework.security.authentication.TestingAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;

class DescriptionAuthorizerServiceTest {
  private static final String TEST_ACCOUNT = "testAccount";
  private static final List<String> APPLICATIONS = Arrays.asList("testApplication", null);
  private static final List<String> RESOURCES = Arrays.asList("testResource1", "testResource2", null);
  private static final String APPLICATION_PERMISSION_TYPE = "APPLICATION";
  private static final String WRITE_PERMISSION = "WRITE";

  Registry registry;
  FiatPermissionEvaluator evaluator;
  AccountDefinitionSecretManager secretManager;
  SecurityConfig.OperationsSecurityConfigurationProperties opsSecurityConfigProps;
  DescriptionAuthorizerService service;

  @BeforeEach
  void setup() {
    registry = new NoopRegistry();
    evaluator = mock(FiatPermissionEvaluator.class);
    secretManager = mock(AccountDefinitionSecretManager.class);
    opsSecurityConfigProps = new SecurityConfig.OperationsSecurityConfigurationProperties();
    service =
        new DescriptionAuthorizerService(
            registry, Optional.of(evaluator), opsSecurityConfigProps, secretManager);
  }

  @Test
  void shouldAuthorizeDescriptionWithAccessToAccountAndApplications() {
    given(secretManager.canAccessAccountWithSecrets(anyString(), eq(TEST_ACCOUNT)))
        .willReturn(true);
    given(evaluator.hasPermission(any(Authentication.class), any(Serializable.class), eq(APPLICATION_PERMISSION_TYPE), eq(WRITE_PERMISSION)))
        .willReturn(true);

    givenAuthenticatedUser();

    var description = new TestDescription(TEST_ACCOUNT, APPLICATIONS, RESOURCES);
    var errors = new DescriptionValidationErrors(description);

    service.authorize(description, errors);

    assertThat(errors.getAllErrors()).isEmpty();
    verify(evaluator).storeWholePermission();
    verify(evaluator, times(3)).hasPermission(any(Authentication.class), any(Serializable.class), eq(APPLICATION_PERMISSION_TYPE), eq(WRITE_PERMISSION));
    verify(secretManager).canAccessAccountWithSecrets(anyString(), eq(TEST_ACCOUNT));
  }

  @ParameterizedTest(name = "account access: {0}, application access: {1}")
  @MethodSource("accountAndApplicationAccessOutcomes")
  void shouldDenyAccessToAccountAndOrApplications(
      boolean accountAccessible, boolean applicationAccessible, int expectedNumberOfErrors) {
    given(secretManager.canAccessAccountWithSecrets(anyString(), eq(TEST_ACCOUNT)))
        .willReturn(accountAccessible);
    given(evaluator.hasPermission(any(Authentication.class), any(Serializable.class), eq(APPLICATION_PERMISSION_TYPE), eq(WRITE_PERMISSION)))
        .willReturn(applicationAccessible);

    givenAuthenticatedUser();

    var description = new TestDescription(TEST_ACCOUNT, APPLICATIONS, RESOURCES);
    var errors = new DescriptionValidationErrors(description);

    service.authorize(description, errors);

    verify(evaluator).storeWholePermission();
    verify(evaluator, times(3)).hasPermission(any(Authentication.class), any(Serializable.class), eq(APPLICATION_PERMISSION_TYPE), eq(WRITE_PERMISSION));
    verify(secretManager).canAccessAccountWithSecrets(anyString(), eq(TEST_ACCOUNT));
    assertThat(errors.getAllErrors()).hasSize(expectedNumberOfErrors);
    if (!accountAccessible) {
      assertThat(errors.getGlobalErrors())
          .extracting(e -> e.getCode())
          .contains("authorization.account");
    }
    if (!applicationAccessible) {
      assertThat(errors.getGlobalErrors())
          .extracting(e -> e.getCode())
          .contains("authorization.application");
    }
  }

  static Stream<Arguments> accountAndApplicationAccessOutcomes() {
    return Stream.of(
        Arguments.of(true, false, 3),
        Arguments.of(false, true, 1),
        Arguments.of(false, false, 4));
  }

  @ParameterizedTest(name = "allow list: {0}, account access: {1}")
  @MethodSource("imageTaggingOutcomes")
  void shouldSkipAuthorizationForImageTaggingDescriptionWhenAccountIsAllowListed(
      List<String> allowUnauthenticatedImageTaggingInAccounts,
      boolean accountAccessible,
      int expectedNumberOfErrors,
      boolean expectsAuthorizationCheck) {
    given(secretManager.canAccessAccountWithSecrets(anyString(), eq(TEST_ACCOUNT)))
        .willReturn(accountAccessible);
    opsSecurityConfigProps.setAllowUnauthenticatedImageTaggingInAccounts(
        allowUnauthenticatedImageTaggingInAccounts);

    var description = new TestImageTaggingDescription(TEST_ACCOUNT);
    var errors = new DescriptionValidationErrors(description);

    service.authorize(description, errors);

    assertThat(errors.getAllErrors()).hasSize(expectedNumberOfErrors);
    if (expectsAuthorizationCheck) {
      verify(secretManager).canAccessAccountWithSecrets(anyString(), eq(TEST_ACCOUNT));
    } else {
      verifyNoInteractions(secretManager, evaluator);
    }
  }

  static Stream<Arguments> imageTaggingOutcomes() {
    return Stream.of(
        Arguments.of(List.of(TEST_ACCOUNT), false, 0, false),
        Arguments.of(List.of("anotherAccount"), false, 1, true),
        Arguments.of(List.of("anotherAccount"), true, 0, true),
        Arguments.of(List.of(), false, 1, true));
  }

  @ParameterizedTest(name = "resource type: {0}, account access: {1}")
  @MethodSource("resourceTypeOutcomes")
  void shouldOnlyAuthorizeSpecifiedResourceType(
      ResourceType resourceType,
      boolean accountAccessible,
      int expectedNumberOfErrors,
      int expectedNumberOfAuthenticationChecks) {
    given(secretManager.canAccessAccountWithSecrets(anyString(), eq(TEST_ACCOUNT)))
        .willReturn(accountAccessible);
    given(evaluator.hasPermission(any(Authentication.class), any(Serializable.class), eq(APPLICATION_PERMISSION_TYPE), eq(WRITE_PERMISSION)))
        .willReturn(false);

    givenAuthenticatedUser();

    var description = new TestDescription(TEST_ACCOUNT, APPLICATIONS, RESOURCES);
    var errors = new DescriptionValidationErrors(description);

    service.authorize(description, errors, List.of(resourceType));

    verify(evaluator, times(expectedNumberOfAuthenticationChecks))
        .hasPermission(any(Authentication.class), any(Serializable.class), eq(APPLICATION_PERMISSION_TYPE), eq(WRITE_PERMISSION));
    assertThat(errors.getAllErrors()).hasSize(expectedNumberOfErrors);
  }

  static Stream<Arguments> resourceTypeOutcomes() {
    return Stream.of(
        Arguments.of(ResourceType.APPLICATION, false, 3, 3),
        Arguments.of(ResourceType.ACCOUNT, true, 0, 0),
        Arguments.of(ResourceType.ACCOUNT, false, 1, 0));
  }

  private void givenAuthenticatedUser() {
    var authentication = new TestingAuthenticationToken(null, null);
    var context = SecurityContextHolder.createEmptyContext();
    context.setAuthentication(authentication);
    SecurityContextHolder.setContext(context);
  }

  static class TestDescription implements AccountNameable, ApplicationNameable, ResourcesNameable {
    private final String account;
    private final Collection<String> applications;
    private final List<String> names;

    TestDescription(String account, Collection<String> applications, List<String> names) {
      this.account = account;
      this.applications = applications;
      this.names = names;
    }

    @Override
    public String getAccount() {
      return account;
    }

    @Override
    public Collection<String> getApplications() {
      return applications;
    }

    @Override
    public Collection<String> getNames() {
      return names;
    }
  }

  static class TestImageTaggingDescription implements AccountNameable {
    private final String account;

    TestImageTaggingDescription(String account) {
      this.account = account;
    }

    @Override
    public String getAccount() {
      return account;
    }

    @Override
    public boolean requiresApplicationRestriction() {
      return false;
    }

    @Override
    public boolean requiresAuthorization(
        SecurityConfig.OperationsSecurityConfigurationProperties opsSecurityConfigProps) {
      return !opsSecurityConfigProps.getAllowUnauthenticatedImageTaggingInAccounts().contains(account);
    }
  }
}

