class DefaultAccountSecurityPolicyTest {
  private static final String USERNAME = "user";
  private static final String ACCOUNT = "account";

  FiatPermissionEvaluator permissionEvaluator;
  DefaultAccountSecurityPolicy policy;

  @BeforeEach
  void setup() {
    permissionEvaluator = mock(FiatPermissionEvaluator.class);
    policy = new DefaultAccountSecurityPolicy(permissionEvaluator);
  }

  @Test
  void isAdminReturnsTrueWhenUserIsAdmin() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(adminPermission());

    assertThat(policy.isAdmin(USERNAME)).isTrue();
  }

  @Test
  void isAdminReturnsFalseWhenUserIsNotAdmin() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(permission(false));

    assertThat(policy.isAdmin(USERNAME)).isFalse();
  }

  @Test
  void isAdminReturnsFalseWhenNoPermissionExists() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(null);

    assertThat(policy.isAdmin(USERNAME)).isFalse();
  }

  @Test
  void isAccountManagerReturnsTrueWhenUserIsAdmin() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(adminPermission());

    assertThat(policy.isAccountManager(USERNAME)).isTrue();
  }

  @Test
  void isAccountManagerReturnsFalseWhenUserIsNotAdmin() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(permission(false));

    assertThat(policy.isAccountManager(USERNAME)).isFalse();
  }

  @Test
  void isAccountManagerReturnsFalseWhenNoPermissionExists() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(null);

    assertThat(policy.isAccountManager(USERNAME)).isFalse();
  }

  @Test
  void getRolesReturnsRoleNamesWhenPermissionExists() {
    given(permissionEvaluator.getPermission(USERNAME))
        .willReturn(permissionWithRoles("dev", "ops"));

    assertThat(policy.getRoles(USERNAME)).containsExactlyInAnyOrder("dev", "ops");
  }

  @Test
  void getRolesReturnsEmptySetWhenNoPermissionExists() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(null);

    assertThat(policy.getRoles(USERNAME)).isEmpty();
  }

  @Test
  void canUseAccountReturnsTrueWhenUserIsAdmin() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(adminPermission());

    assertThat(policy.canUseAccount(USERNAME, ACCOUNT)).isTrue();
  }

  @Test
  void canUseAccountReturnsTrueWhenUserHasWritePermissionOnAccount() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(permission(false));
    given(permissionEvaluator.hasPermission(eq(USERNAME), eq(ACCOUNT), eq(ResourceType.ACCOUNT.getName()), eq(Authorization.WRITE)))
        .willReturn(true);

    assertThat(policy.canUseAccount(USERNAME, ACCOUNT)).isTrue();
  }

  @Test
  void canUseAccountReturnsFalseWhenUserIsNotAdminAndLacksWritePermission() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(permission(false));
    given(permissionEvaluator.hasPermission(eq(USERNAME), eq(ACCOUNT), eq(ResourceType.ACCOUNT.getName()), eq(Authorization.WRITE)))
        .willReturn(false);

    assertThat(policy.canUseAccount(USERNAME, ACCOUNT)).isFalse();
  }

  @Test
  void canUseAccountReturnsFalseWhenNoPermissionExists() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(null);

    assertThat(policy.canUseAccount(USERNAME, ACCOUNT)).isFalse();
  }

  @Test
  void canModifyAccountReturnsTrueWhenUserIsAdmin() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(adminPermission());

    assertThat(policy.canModifyAccount(USERNAME, ACCOUNT)).isTrue();
  }

  @Test
  void canModifyAccountReturnsTrueWhenUserIsAccountManagerWithWritePermissionOnAccount() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(permission(false));
    given(permissionEvaluator.hasPermission(eq(USERNAME), eq(ACCOUNT), eq(ResourceType.ACCOUNT.getName()), eq(Authorization.WRITE)))
        .willReturn(true);

    assertThat(policy.canModifyAccount(USERNAME, ACCOUNT)).isTrue();
  }

  @Test
  void canModifyAccountReturnsFalseWhenUserIsNotAdminAndLacksWritePermission() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(permission(false));
    given(permissionEvaluator.hasPermission(eq(USERNAME), eq(ACCOUNT), eq(ResourceType.ACCOUNT.getName()), eq(Authorization.WRITE)))
        .willReturn(false);

    assertThat(policy.canModifyAccount(USERNAME, ACCOUNT)).isFalse();
  }

  @Test
  void canModifyAccountReturnsFalseWhenNoPermissionExists() {
    given(permissionEvaluator.getPermission(USERNAME)).willReturn(null);

    assertThat(policy.canModifyAccount(USERNAME, ACCOUNT)).isFalse();
  }

  private UserPermission.View adminPermission() {
    return permission(true);
  }

  private UserPermission.View permission(boolean admin) {
    var permission = new UserPermission.View();
    permission.setAdmin(admin);
    return permission;
  }

  private UserPermission.View permissionWithRoles(String... roles) {
    var permission = new UserPermission.View();
    Set<Role.View> roleViews = java.util.Arrays.stream(roles).map(DefaultAccountSecurityPolicyTest::role).collect(java.util.stream.Collectors.toSet());
    permission.setRoles(roleViews);
    return permission;
  }

  private static Role.View role(String name) {
    var role = new Role.View();
    role.setName(name);
    return role;
  }
}

