        .isEqualTo(accountManager && hasWritePermission);
  }

  private UserPermission.View adminPermission() {
    return permission(true);
  }

  private UserPermission.View accountManagerPermission() {
    return permission(false, true);
  }

  private UserPermission.View permission(boolean admin) {
    return permission(admin, false);
  }

  private UserPermission.View permission(boolean admin, boolean accountManager) {
    var permission = new UserPermission.View();
    permission.setAdmin(admin);
    permission.setAccountManager(accountManager);
    return permission;
  }

