package com.netflix.spinnaker.clouddriver.security;

import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.mock;

import com.netflix.spinnaker.clouddriver.security.AccountDefinitionService.AccountAction;
import com.netflix.spinnaker.credentials.definition.CredentialsDefinition;
import com.netflix.spinnaker.kork.secrets.user.UserSecret;
import com.netflix.spinnaker.kork.web.exceptions.InvalidRequestException;
import io.spinnaker.test.security.ValueAccount;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.security.access.AccessDeniedException;

class AccountDefinitionServiceTest {
  AccountDefinitionRepository repository;
  AccountDefinitionSecretManager secretManager;
  AccountCredentialsProvider accountCredentialsProvider;
  AccountSecurityPolicy policy;
  AuthorizedRolesExtractor extractor;
  AccountDefinitionService service;

  @BeforeEach
  void setup() {
    repository = mock(AccountDefinitionRepository.class);
    secretManager = mock(AccountDefinitionSecretManager.class);
    accountCredentialsProvider = mock(AccountCredentialsProvider.class);
    policy = mock(AccountSecurityPolicy.class);
    extractor = mock(AuthorizedRolesExtractor.class);
    service =
        new AccountDefinitionService(
            repository, secretManager, accountCredentialsProvider, policy, List.of(extractor));
  }

  @Test
  void validateAccountAuthorizationAllowsCommonRole() {
    given(extractor.supportsType(any())).willReturn(true);
    given(extractor.getAuthorizedRoles(any())).willReturn(Set.of("dev"));
    var definition = ValueAccount.builder().name("account").value("value").build();

    assertDoesNotThrow(
        () ->
            service.validateAccountAuthorization(
                Set.of("dev", "ops"), definition, AccountAction.CREATE));
  }

  @Test
  void validateAccountAuthorizationAllowsEmptyAuthorizedRoles() {
    given(extractor.supportsType(any())).willReturn(true);
    given(extractor.getAuthorizedRoles(any())).willReturn(Set.of());
    var definition = ValueAccount.builder().name("account").value("value").build();

    assertDoesNotThrow(
        () -> service.validateAccountAuthorization(Set.of("ops"), definition, AccountAction.CREATE));
  }

  @Test
  void validateAccountAuthorizationThrowsForNoCommonRole() {
    given(extractor.supportsType(any())).willReturn(true);
    given(extractor.getAuthorizedRoles(any())).willReturn(Set.of("dev"));
    var definition = ValueAccount.builder().name("account").value("value").build();

    assertThatThrownBy(
            () ->
                service.validateAccountAuthorization(
                    Set.of("ops"), definition, AccountAction.CREATE))
        .isInstanceOf(InvalidRequestException.class)
        .hasMessageContaining("account");
  }

  @Test
  void validateUserSecretAuthorizationAllowsCommonRole() {
    var userSecret = mock(UserSecret.class);
    given(userSecret.getRoles()).willReturn(List.of("group"));
    given(secretManager.getUserSecret(any())).willReturn(userSecret);
    var definition = ValueAccount.builder().name("account").value("secret://test?k=foo").build();

    assertDoesNotThrow(
        () ->
            service.validateUserSecretAuthorization(
                Set.of("group"), definition, AccountAction.CREATE));
  }

  @Test
  void validateUserSecretAuthorizationThrowsForNoCommonRole() {
    var userSecret = mock(UserSecret.class);
    given(userSecret.getRoles()).willReturn(List.of("group"));
    given(secretManager.getUserSecret(any())).willReturn(userSecret);
    var definition = ValueAccount.builder().name("account").value("secret://test?k=foo").build();

    assertThatThrownBy(
            () ->
                service.validateUserSecretAuthorization(
                    Set.of("other"), definition, AccountAction.SAVE))
        .isInstanceOf(AccessDeniedException.class);
  }

  @Test
  void validateUserSecretAuthorizationCanReadPrivateFields() {
    var userSecret = mock(UserSecret.class);
    given(userSecret.getRoles()).willReturn(List.of("group"));
    given(secretManager.getUserSecret(any())).willReturn(userSecret);
    var definition = new PrivateStringFieldsAccount("account", "secret://test?k=foo");

    assertDoesNotThrow(
        () ->
            service.validateUserSecretAuthorization(
                Set.of("group"), definition, AccountAction.UPDATE));
  }

  @Test
  void validateAccountAuthorizationThrowsWhenNoExtractorSupportsType() {
    given(extractor.supportsType(any())).willReturn(false);
    var definition = ValueAccount.builder().name("account").value("value").build();

    assertDoesNotThrow(
        () -> service.validateAccountAuthorization(Set.of("ops"), definition, AccountAction.CREATE));
  }

  @Test
  void validateUserSecretAuthorizationIgnoresNonUserSecretFields() {
    given(extractor.supportsType(anyString())).willReturn(false);
    var definition = ValueAccount.builder().name("account").value("plain value").build();

    assertDoesNotThrow(
        () ->
            service.validateUserSecretAuthorization(
                Set.of("other"), definition, AccountAction.CREATE));
  }

  static class PrivateStringFieldsAccount implements CredentialsDefinition {
    private final String name;
    private final String password;

    PrivateStringFieldsAccount(String name, String password) {
      this.name = name;
      this.password = password;
    }

    @Override
    public String getName() {
      return name;
    }
  }
}

